<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Portal admin | AIS</title><link rel="stylesheet" href="admin.css"></head><body class="admin-page"><main class="admin-shell"><header class="admin-header"><div><h1>Portal cards</h1><p>Changes are published immediately.</p></div><nav><a class="button secondary" href="../">View portal</a><a class="button secondary" href="logout.php">Sign out</a><a class="button" href="edit.php">Add card</a></nav></header><?php if ($message): ?><div class="notice success"><?= portal_escape($message) ?></div><?php endif; ?><section class="card-list"><?php foreach ($cards as $card): ?><article class="admin-card"><div class="card-copy"><h2><?= portal_escape($card['title']) ?> <?php if (!$card['is_active']): ?><small>Hidden</small><?php endif; ?></h2><p><?= portal_escape($card['description']) ?></p><a href="<?= portal_escape($card['url']) ?>" target="_blank" rel="noopener noreferrer"><?= portal_escape($card['url']) ?></a></div><div class="card-actions"><form method="post" action="move.php"><input type="hidden" name="csrf_token" value="<?= portal_escape(admin_csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int) $card['id'] ?>"><button name="direction" value="up" title="Move up" aria-label="Move up">&#8593;</button><button name="direction" value="down" title="Move down" aria-label="Move down">&#8595;</button></form><a class="button secondary" href="edit.php?id=<?= (int) $card['id'] ?>">Edit</a><form method="post" action="delete.php" onsubmit="return confirm('Delete this card?');"><input type="hidden" name="csrf_token" value="<?= portal_escape(admin_csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int) $card['id'] ?>"><button class="danger" type="submit">Delete</button></form></div></article><?php endforeach; ?></section></main></body></html>
